{"description":"保存单项清单并逐项提交生成请求","command":"python3 - <<'PY'
import json,uuid,pathlib
p=pathlib.Path('.')
for i in range(1,12):
 f=p/'input'/f'prompt-{i:02}.txt'; f.read_text(encoding='utf-8')
 item={'request_id':str(uuid.uuid4()),'request':{'title':f'图片 {i}','instance_id':'1','template_id':'1','model':None,'parameters':{'seed':424241+i,'batch_size':1,'width':512,'height':512},'loras':[]},'parameter_files':{'positive_prompt':str(f)}}
 (p/f'manifest-{i:02}.json').write_text(json.dumps({'items':[item]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
PY
for i in $(seq -w 1 11); do echo "--- $i ---"; result=$(ELECTRON_RUN_AS_NODE=1 "$DSH_HARNESS_COMFYUI_NODE_EXECUTABLE" --expose-internals "$DSH_HARNESS_COMFYUI_CLI" --quiet generation submit --file "$(pwd)/manifest-$i.json") || { echo "提交失败 $i"; exit 1; }; cat "$result"; echo; cp "$result" "submission-$i.json" || exit $?; done","timeoutMs":120000}

